async function handleListSessions(
  ws: WebSocket,
  session: ChatSession,
  sessionStore: SessionStore | undefined,
  message: {type: 'list_sessions'; limit?: number; before?: {sessionId: string; updatedAt: string | number}}
): Promise<void> {
  if (!sessionStore?.listFor) {
    sendError(ws, ErrorCodes.UNSUPPORTED, 'Conversation list not available');
    return;
  }

  try {
    const summaries = await sessionStore.listFor(session.userId, {limit: message.limit, before: message.before});
    const sessions = summaries.map(s => ({
      sessionId: s.sessionId,
      createdAt: s.createdAt instanceof Date ? s.createdAt.toISOString() : s.createdAt,
      updatedAt: s.updatedAt instanceof Date ? s.updatedAt.toISOString() : s.updatedAt,
      entryCount: s.entryCount,
    }));
    sendJson(ws, {type: 'session_list', sessions});
  } catch (error) {
    const message = error instanceof Error ? error.message : 'Unknown error';
    log.error('ws', 'list_sessions failed', {userId: session.userId, error: message});
    sendError(ws, ErrorCodes.SERVER_ERROR, 'Failed to retrieve conversation list');
  }
}

function handlePing(ws: WebSocket, timestamp: number): void {
  ws.send(JSON.stringify({type: 'pong', timestamp}));
}

